INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.107.0',
  '2026-10-01',
  'Игры: один список, настройки у каждой игры и картинка на всё поле',
  E'Деление на «одиночные» и «с друзьями» убрано — игры лежат одним списком. Когда появятся игры на двоих, у них на плитке будет человечек: нажали — позвали друга.\n\nНастройки переехали в саму игру: у каждой плитки своя шестерёнка, а в ней только то, что относится к этой игре.\n\nКартинка теперь ложится фоном под всё поле, а не под сетку. Поверх неё интерфейс игры становится светлым сам, независимо от темы приложения. У «найди пару» отдельным набором выбирается рубашка карт — фон и рубашка больше не спорят друг с другом. Костяшки пятнашек стали белыми полупрозрачными плашками с рамкой: на любом фото видно и цифры, и саму картинку.',
  E'Миграция 0156: в game_backgrounds добавлен slot (''game'' по умолчанию) и переложен первичный ключ на (user_id, game, slot, image_id); старые строки уехали в слот «game» сами. Допустимые слоты перечислены в gameRules рядом с направлением рекорда, ручка стала PUT /games/{game}/backgrounds/{slot}, в ответе backgrounds теперь игра → слот → картинки.\n\nФон партии рисует страница (.stage в GamesView), а не игра. Там же поверх картинки переопределяются переменные темы (--text-color, --card-color, --cell-bg-color, --bg-color): внутри сцены всё светлое независимо от темы приложения, и ни одной игре не нужно знать, лежит под ней картинка или нет. Из Game2048 и GameFifteen ушла работа с картинкой целиком (в пятнашках — вместе с нарезкой на костяшки), GamePairs получил cardBg. Вкладки в GamesView заменены списком с «⚙» у каждой игры и отдельным экраном настроек; GamesSettings.vue стал GameSettings.vue и работает с одной игрой и её слотами. В GameInfo добавлен флаг invite — у таких игр на плитке появится человечек.\n\nПроверено в браузере: список без вкладок, шестерёнка каждой игры, выбор разных картинок в «фон игры» и «рубашку карт» у «найди пару» и их появление в партии, белые костяшки с рамкой поверх фото в пятнашках, 2048 на картинке со светлым интерфейсом.'
);
-- +goose StatementEnd

